<?php
require_once __DIR__ . '/auth.php'; require_json_access('edit_dishes'); $dish_id = (int) ($_POST['dish_id'] ?? 0); $name = trim($_POST['dish_name'] ?? ''); $desc = trim($_POST['dish_desc'] ?? ''); $price = $_POST['dish_price'] ?? ''; if ($dish_id <= 0) { json_out(['success' => false, 'message' => 'Invalid dish ID.'], 400); } if ($name === '' || mb_strlen($name) > 100) { json_out(['success' => false, 'message' => 'Dish name must be 1-100 characters.'], 400); } if (mb_strlen($desc) > 500) { json_out(['success' => false, 'message' => 'Description too long (max 500 chars).'], 400); } if (!is_numeric($price) || (float) $price < 0) { json_out(['success' => false, 'message' => 'Price must be a non-negative number.'], 400); } try { $pdo = db(); $stmt = $pdo->prepare("SELECT dish_id FROM menu WHERE dish_id = :dish_id"); $stmt->execute([':dish_id' => $dish_id]); if (!$stmt->fetch()) { json_out(['success' => false, 'message' => 'Dish not found.'], 404); } $stmt = $pdo->prepare("UPDATE menu SET dish_name = :name, dish_desc = :desc, dish_price = :price WHERE dish_id = :id"); $stmt->execute([ ':name' => $name, ':desc' => $desc, ':price' => (float) $price, ':id' => $dish_id, ]); json_out([ 'success' => true, 'message' => 'Dish updated.', 'dish' => [ 'dish_id' => $dish_id, 'dish_name' => $name, 'dish_desc' => $desc, 'dish_price' => number_format((float) $price, 2, '.', ''), ], ]); } catch (PDOException $e) { json_out(['success' => false, 'message' => 'Error updating dish.'], 500); } exit();